"""Present the exact N20 AC6 three-copy exclusion and AC5 witness."""
from pathlib import Path
import json,html,re,hashlib
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def m(tex,display=True):
 tag='div'if display else'span';return f'<{tag} class="math" data-display="{str(display).lower()}" data-tex="{html.escape(tex,quote=True)}"></{tag}>'
def links(items):return '<div class="proof-links">'+''.join(f'<a href="{u}">{t} ↗</a>'for u,t in items)+'</div>'
def main():
 r=json.loads((HERE/'independent-verification.json').read_text());assert r['passed']and r['certificateSHA256']==hashlib.sha256((HERE/'certificate.json').read_bytes()).hexdigest()
 css=re.search(r'<style>(.*?)</style>',(ROOT/'research/t2-qec-upper/index.html').read_text(),re.S).group(1)+'\n.math{max-width:100%;overflow-x:auto}.badge{color:#1c6253;text-transform:uppercase;font-size:.8rem;letter-spacing:.08em}'
 b='<p class="eyebrow">Anticoherent states and subspaces · Exact three-copy proof</p><a href="../../index.html#n=20&t=6">← Catalogue entry</a><h1>Twenty qubits: maximum pure AC order is five</h1><div class="result"><span class="badge">Proved · arbitrary complex states</span>'+m(r'\boxed{K(20,t)=0\quad(t\ge6),\qquad t_{\max}(20)=5.}')+'<p>A three-copy matrix-positivity certificate excludes every sixth-order state. The existing analytical fifth-order state attains the maximum order.</p></div>'
 b+='<section><h2>The exact contradiction</h2><p>A hypothetical normalized AC6 state supplies the positive, trace-one moment</p>'+m(r'X=\int_{\mathrm{SU}(2)}(U_g|\psi\rangle\langle\psi|U_g^\dagger)^{\otimes3}\,dg.')+'<p>It lies on '+m(r'\operatorname{Sym}^3(V_{10})',False)+', of dimension 1771, with 29 total-spin blocks and 108 real symmetric multiplicity coordinates. Sixth-order anticoherence gives</p>'+m(r'\operatorname{Tr}_1[(T_{\ell0}\otimes I^{\otimes2})X]=0,\qquad\ell=1,\ldots,6.')+'<p>From 95 selected necessary physical equations, an exact rational combination gives</p>'+m(r'0=\operatorname{Tr}X+\sum_J\operatorname{Tr}(C_Jx_J),\qquad C_J\succ0,\quad x_J\succeq0.')+'<p>Here '+m(r'x_J=d_J(2J+1)S_JB_JS_J',False)+' are the certificate’s positively rescaled multiplicity matrices. All terms on the right are nonnegative and the first equals one, a contradiction.</p><p>All 61 positive rational LDL pivots are checked exactly. The independent verifier rebuilds every equation and physical trace from ordered tensor words. Taking real parts in a real angular-momentum basis preserves positivity and the selected equations, so arbitrary complex states are covered. No partial-transpose condition or restricted support is used.</p>'+links([('proof.tex','Complete LaTeX proof'),('certificate.json','Exact rational certificate'),('verify_independently.py','Independent verifier'),('independent-verification.json','Successful exact reconstruction'),('positive-control.json','Physical positive controls')])+'</section>'
 b+='<section><h2>Order five is attained</h2>'+m(r'\begin{aligned}75|\psi_5\rangle={}&\sqrt{561}(|D_{20}^{(0)}\rangle+|D_{20}^{(20)}\rangle)\\&+3\sqrt{209}(|D_{20}^{(5)}\rangle-|D_{20}^{(15)}\rangle)\\&+\sqrt{741}|D_{20}^{(10)}\rangle.\end{aligned}')+'<p>This exact representative is already in the supplied Julia file and AC-state catalogue. Its diagonal moments satisfy</p>'+m(r'\langle J_z^2\rangle=\frac{110}{3},\qquad\langle J_z^4\rangle=\frac{7238}{3}.')+'<p>Reflection symmetry cancels odd moments, support gaps remove shifts one through four, and opposite signs at Dicke indices five and fifteen cancel shift-five coherences pairwise. Its fifth reduced state is '+m(r'I_6/6',False)+'. Together with the exclusion, this establishes the maximum pure-state order.</p>'+links([('../../../anticoherent-state-catalogue/index.html#n=20&t=5&state=acliege-n20-t5','Matching AC-state witness')])+'</section>'
 head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>N20 maximum pure AC order is five</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-tex]").forEach(el=>{if(window.katex)el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==="true",throwOnError:false,strict:"ignore",trust:false});}));</script></head><body><main>'
 (HERE/'index.html').write_text(head+b+'</main></body></html>\n')
if __name__=='__main__':main()
